<script setup>
import { ref } from 'vue';
import { Store } from '../store';
import Icon from './ui/EditionIcon.vue';
const email=ref(''),password=ref(''),busy=ref(false),error=ref('');
async function login(){ if(busy.value)return; busy.value=true;error.value='';try{if(!await Store.login(email.value,password.value))error.value='Check your email and password, then try again.';}finally{busy.value=false;} }
</script>
<template><div class="ed-login"><section class="ed-login-story"><div class="ed-brand"><span class="ed-brandmark"><i></i><i></i><i></i><i></i></span>myfin<small>edition</small></div><div><div class="ed-eyebrow">A little clarity. Every day.</div><h1>More room for<br>your business.</h1><p>Your products, your people, your next good sale. Together in one considered workspace.</p><div class="ed-login-lines" aria-hidden="true"></div></div><footer class="ed-eyebrow">THE EVERYDAY BUSINESS WORKSPACE</footer></section><section class="ed-login-form"><div class="ed-eyebrow">WELCOME BACK</div><h1>A fresh start<br>to a good day.</h1><p class="ed-muted">Sign in to your store workspace.</p><form @submit.prevent="login"><div class="ed-field"><label for="login-email">Email address</label><input id="login-email" v-model="email" type="email" autocomplete="username" placeholder="you@yourstore.com" required></div><div class="ed-field"><label for="login-password">Password</label><input id="login-password" v-model="password" type="password" autocomplete="current-password" placeholder="Your password" required></div><p v-if="error" class="ed-login-error" role="alert">{{ error }}</p><button class="ed-btn primary" type="submit" :disabled="busy">{{ busy?'Signing in…':'Sign in to workspace' }}<Icon name="arrow" /></button></form><footer>Use your existing MyFin account. Your store records are ready when you are.<span v-if="Store.state.offlineStatus" style="display:block;margin-top:12px" role="status">{{ Store.state.offlineStatus }}</span></footer></section></div></template>
